messages.content:
1	# 算子模板
2	
3	> 每个算子在 `csrc/ops/<op>/` 下建子目录，复制以下模板填充。`<op>` 取评测集算子原型定义（如 cann-bench `proto.yaml`）的 `operator.name`（小写），目录名与之一致。权威样例见 direct launch 工程样例（如 cann-bench `examples/direct_launch_example/csrc/ops/{add,sqrt}/`）。
4	
5	## 算子目录结构
6	
7	```
8	csrc/ops/<op>/
9	├── CMakeLists.txt          # 算子自注册（见下方）
10	├── op_kernel/
11	│   ├── <op>_kernel.cpp     # bisheng 编译：Kernel 类 + Tiling + extern "C" Launch（见下方）
12	│   └── <op>_launch.h       # Launch 声明，g++ 可见（见下方）
13	└── op_plugin/
14	    └── <op>_plugin.cpp     # g++ 编译：torch.library 注册 + Meta + NPU impl（见下方）
15	```
16	
17	## 模板选择规则
18	
19	direct launch 算子统一一套模板，按算子复杂度调整 Kernel 类内部实现：
20	
21	| 算子类型 | Kernel 模板调整点 |
22	|----------|-------------------|
23	| Element-wise / Activation（L1） | 单输入单输出，CopyIn→Compute→CopyOut 三段式，tiling 按 element count 切 |
24	| Reduction / Norm（L2） | 多输入或归约，需 ReduceSum/ReduceMax，注意尾块非对齐 |
25	| Conv / Matmul / MoE（L3） | CUBE 运算（Mmad），多 Tiling 策略，多核切分复杂 |
26	| Attention / RNN（L4） | 多算子融合，复杂数据流，多 stage 流水。**Attention 类**：走原生单 kernel CV 融合——仅一个 `__global__` 核函数，Cube（`Mmad` 等原生原语实现矩阵乘）与 Vector 逻辑同核实现并设计 CV 跨核同步，严禁拆为多个核函数（多 kernel 判不通过） |
27	
28	> 通用 Ascend C kernel 编写范式（Tiling 设计、Buffer 规划、数据流方法论）参照 `ascendc-tiling-design`；代码架构选型（SIMD 载体 MemBase/RegBase/Cube 与 SIMT 路线）参照 `repo-knowledge`。
29	
30	## op_kernel/<op>_kernel.cpp（bisheng 编译）
31	
32	以 sqrt 为样例的模板。`<op>` / `<Op>` / 输入输出参数 / Kernel 计算逻辑按 `proto.yaml` 替换：
33	
34	```cpp
35	/**
36	 * <Op> 算子 - Kernel + Tiling + Launch
37	 * 编译：bisheng --npu-arch=<arch> -xasc
38	 */
39	#include <tuple>
40	#include <algorithm>
41	#include <type_traits>
42	#include "kernel_operator.h"
43	#include "platform/platform_ascendc.h"
44	
45	constexpr static int64_t PIPELINE_DEPTH = 2;
46	
47	template <typename T>
48	class Kernel<Op> {
49	public:
50	    __aicore__ inline Kernel<Op>() {}
51	
52	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
53	                                int64_t totalLength, int64_t blockLength, uint32_t tileSize)
54	    {
55	        // 1. GlobalTensor 绑定（按 blockIdx 偏移）
56	        xGm_.SetGlobalBuffer((__gm__ T *)x + blockLength * AscendC::GetBlockIdx());
57	        yGm_.SetGlobalBuffer((__gm__ T *)y + blockLength * AscendC::GetBlockIdx());
58	        // 2. InitBuffer（TQue / TBuf，按 tileSize * sizeof(T)）
59	        pipe_.InitBuffer(inQueueX_,  PIPELINE_DEPTH, tileSize * sizeof(T));
60	        pipe_.InitBuffer(outQueueY_, PIPELINE_DEPTH, tileSize * sizeof(T));
61	        // 3. 计算 tileNum / tailTileElementNum（处理尾块非对齐）
62	        int64_t currentBlockLength = totalLength - AscendC::GetBlockIdx() * blockLength;
63	        if (currentBlockLength > blockLength) currentBlockLength = blockLength;
64	        if (currentBlockLength < 0) currentBlockLength = 0;
65	        elementNumPerTile_ = tileSize;
66	        tileNum_ = currentBlockLength / elementNumPerTile_;
67	        tailTileElementNum_ = currentBlockLength - tileNum_ * elementNumPerTile_;
68	    }
69	
70	    __aicore__ inline void Process()
71	    {
72	        // 三段式流水：CopyIn → Compute → CopyOut，循环 tile + 尾块
73	        for (int64_t i = 0; i < tileNum_; ++i) {
74	            CopyIn(i * elementNumPerTile_, elementNumPerTile_);
75	            Compute(elementNumPerTile_);
76	            CopyOut(i * elementNumPerTile_, elementNumPerTile_);
77	        }
78	        if (tailTileElementNum_ > 0) {
79	            CopyIn(tileNum_ * elementNumPerTile_, tailTileElementNum_);
80	            Compute(tailTileElementNum_);
81	            CopyOut(tileNum_ * elementNumPerTile_, tailTileElementNum_);
82	        }
83	    }
84	
85	private:
86	    __aicore__ inline void CopyIn(int64_t offset, int64_t count)
87	    {
88	        // DataCopyPad 搬入（处理非对齐，禁用 DataCopy）
89	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
90	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
91	        auto xLocal = inQueueX_.AllocTensor<T>();
92	        AscendC::DataCopyPad(xLocal, xGm_[offset], copyParams, padParams);
93	        inQueueX_.EnQue(xLocal);
94	    }
95	
96	    __aicore__ inline void Compute(int64_t count)
97	    {
98	        auto xLocal = inQueueX_.DeQue<T>();
99	        auto yLocal = outQueueY_.AllocTensor<T>();
100	        // === 核心计算：按 proto.yaml 公式用 Ascend C 原语实现 ===
101	        AscendC::<Op>(yLocal, xLocal, count);  // 替换为实际 Ascend C API
102	        // === 注意 dtype 无原生重载时需 Cast 中转（见 sqrt 样例 fp16/bf16 路径）===
103	        outQueueY_.EnQue(yLocal);
104	        inQueueX_.FreeTensor(xLocal);
105	    }
106	
107	    __aicore__ inline void CopyOut(int64_t offset, int64_t count)
108	    {
109	        auto yLocal = outQueueY_.DeQue<T>();
110	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(count * sizeof(T)), 0, 0, 0};
111	        AscendC::DataCopyPad(yGm_[offset], yLocal, copyParams);
112	        outQueueY_.FreeTensor(yLocal);
113	    }
114	
115	    AscendC::TPipe pipe_;
116	    AscendC::GlobalTensor<T> xGm_, yGm_;
117	    AscendC::TQue<AscendC::TPosition::VECIN,  PIPELINE_DEPTH> inQueueX_;
118	    AscendC::TQue<AscendC::TPosition::VECOUT, PIPELINE_DEPTH> outQueueY_;
119	    int64_t elementNumPerTile_ = 0, tileNum_ = 0, tailTileElementNum_ = 0;
120	};
121	
122	// Kernel 函数（<<<>>> launch 语法，bisheng -xasc 模式有效）
123	template <typename T>
124	__global__ __aicore__ __vector__ void <op>_kernel(GM_ADDR x, GM_ADDR y,
125	    int64_t totalLength, int64_t blockLength, uint32_t tileSize)
126	{
127	    Kernel<Op><T> op;
128	    op.Init(x, y, totalLength, blockLength, tileSize);
129	    op.Process();
130	}
131	
132	// Tiling 计算（返回 numBlocks, blockLength, tileSize）
133	std::tuple<int64_t, int64_t, int64_t> calc_<op>_tiling_params(int64_t totalLength)
134	{
135	    constexpr static int64_t MIN_ELEMS_PER_CORE = 1024;
136	    constexpr static uint32_t FIXED_TILE_ELEMS = 2048;  // 按目标 SoC UB 容量验证
137	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
138	    int64_t coreNum = ascendcPlatform->GetCoreNumAiv();
139	    if (coreNum <= 0) coreNum = 1;
140	    int64_t numBlocks = std::min(coreNum, (totalLength + MIN_ELEMS_PER_CORE - 1) / MIN_ELEMS_PER_CORE);
141	    numBlocks = std::max(numBlocks, static_cast<int64_t>(1));
142	    int64_t blockLength = (totalLength + numBlocks - 1) / numBlocks;
143	    return std::make_tuple(numBlocks, blockLength, static_cast<int64_t>(FIXED_TILE_ELEMS));
144	}
145	
146	// extern "C" Launch 函数（每个 dtype 一个，供 plugin 调用）
147	extern "C" {
148	void launch_<op>_kernel_float(GM_ADDR x, GM_ADDR y,
149	    int64_t totalLength, int64_t numBlocks, int64_t blockLength, uint32_t tileSize, void* stream) {
150	    <op>_kernel<float><<<numBlocks, nullptr, stream>>>(x, y, totalLength, blockLength, tileSize);
151	}
152	void launch_<op>_kernel_half(GM_ADDR x, GM_ADDR y,
153	    int64_t totalLength, int64_t numBlocks, int64_t blockLength, uint32_t tileSize, void* stream) {
154	    <op>_kernel<half><<<numBlocks, nullptr, stream>>>(x, y, totalLength, blockLength, tileSize);
155	}
156	// bfloat16 按需追加
157	}
158	```
159	
160	> **dtype 中转**：部分 Ascend C API 无 fp16/bf16 原生重载（如 `AscendC::Sqrt`），需 Cast 到 fp32 计算再 Cast 回。详见 direct launch 工程样例（如 cann-bench `examples/direct_launch_example/csrc/ops/sqrt/op_kernel/sqrt_kernel.cpp`）。
161	
162	## op_kernel/<op>_launch.h（g++ 可见）
163	
164	Launch 函数声明，供 plugin include：
165	
166	```cpp
167	#ifndef <OP>_LAUNCH_H
168	#define <OP>_LAUNCH_H
169	#include <cstdint>
170	#include <tuple>
171	#ifndef GM_ADDR
172	#define GM_ADDR void*
173	#endif
174	
175	std::tuple<int64_t, int64_t, int64_t> calc_<op>_tiling_params(int64_t totalLength);
176	
177	extern "C" {
178	void launch_<op>_kernel_float(GM_ADDR x, GM_ADDR y,
179	    int64_t totalLength, int64_t numBlocks, int64_t blockLength, uint32_t tileSize, void* stream);
180	void launch_<op>_kernel_half(GM_ADDR x, GM_ADDR y,
181	    int64_t totalLength, int64_t numBlocks, int64_t blockLength, uint32_t tileSize, void* stream);
182	}
183	#endif
184	```
185	
186	## op_plugin/<op>_plugin.cpp（g++ 编译）
187	
188	torch.library 注册 + Meta + NPU 实现。**schema 必须与 `proto.yaml` 的 `schema:` 字段逐字一致**：
189	
190	```cpp
191	#include <ATen/Operators.h>
192	#include <torch/all.h>
193	#include <torch/library.h>
194	#include "torch_npu/csrc/core/npu/NPUStream.h"
195	#include "torch_npu/csrc/framework/OpCommand.h"
196	#include "../op_kernel/<op>_launch.h"
197	
198	namespace cann_bench {  // cann_bench 为评测集约定的包名（<pkg>），此处以 cann_bench 为例
199	
200	// schema 注册 —— 必须与 proto.yaml 的 schema: 逐字一致
201	TORCH_LIBRARY_FRAGMENT(cann_bench, m)
202	{
203	    m.def("<op>(Tensor x) -> Tensor");  // 按 proto.yaml 替换，含 attrs
204	}
205	
206	// Meta 函数（输出 shape/dtype 推导）
207	torch::Tensor <op>_meta(const torch::Tensor &x /*, attrs */) {
208	    return torch::empty_like(x);  // 按 proto.yaml outputs 推导
209	}
210	
211	TORCH_LIBRARY_IMPL(cann_bench, Meta, m)
212	{
213	    m.impl("<op>", <op>_meta);
214	}
215	
216	// NPU 实现（调 tiling + launch kernel）
217	torch::Tensor <op>_npu(const torch::Tensor &x /*, attrs */) {
218	    const c10::OptionalDeviceGuard guard(x.device());
219	    auto y = <op>_meta(x /*, attrs */);
220	    auto stream = c10_npu::getCurrentNPUStream().stream(false);
221	    int64_t totalLength = x.numel();
222	    int64_t numBlocks, blockLength, tileSize;
223	    std::tie(numBlocks, blockLength, tileSize) = calc_<op>_tiling_params(totalLength);
224	    auto x_ptr = (GM_ADDR)x.data_ptr();
225	    auto y_ptr = (GM_ADDR)y.data_ptr();
226	
227	    auto acl_call = [=]() -> int {
228	        auto dtype = x.scalar_type();
229	        if      (dtype == torch::kFloat32) launch_<op>_kernel_float  (x_ptr, y_ptr, totalLength, numBlocks, blockLength, tileSize, stream);
230	        else if (dtype == torch::kFloat16) launch_<op>_kernel_half   (x_ptr, y_ptr, totalLength, numBlocks, blockLength, tileSize, stream);
231	        // bfloat16 按需追加
232	        return 0;
233	    };
234	    at_npu::native::OpCommand::RunOpApi("<Op>", acl_call);  // <Op> 仅作 op name 标签
235	    return y;
236	}
237	
238	TORCH_LIBRARY_IMPL(cann_bench, PrivateUse1, m)
239	{
240	    m.impl("<op>", <op>_npu);
241	}
242	
243	} // namespace cann_bench
244	```
245	
246	> ⚠ **schema 对齐是第一红线**：`m.def(...)` 的签名必须与评测集算子原型定义（如 cann-bench `tasks/levelN/<op>/proto.yaml`）的 `schema:` 字段逐字一致（参数名、类型、默认值、返回值），否则评测注册不上算子。
247	
248	## CMakeLists.txt（算子自注册）
249	
250	```cmake
251	# <Op> 算子自注册
252	set(<OP>_KERNEL_SRCS ${CMAKE_CURRENT_SOURCE_DIR}/op_kernel/<op>_kernel.cpp)
253	set(<OP>_PLUGIN_SRCS ${CMAKE_CURRENT_SOURCE_DIR}/op_plugin/<op>_plugin.cpp)
254	
255	register_direct_launch_op(
256	    "${<OP>_KERNEL_SRCS}" op_kernel
257	    "${<OP>_PLUGIN_SRCS}" op_kernel
258	)
259	```
260	
261	## cann_bench/__init__.py 追加
262	
263	每新增算子，在 `cann_bench/__init__.py` 追加导出：
264	
265	```python
266	def <op>(...) -> torch.Tensor:
267	    return torch.ops.cann_bench.<op>(...)
268	```
