11	/*!
12	 * \file add_example.h
13	 * \brief AddExample 算子 kernel 类定义（arch35 架构）
14	 * 
15	 * 模板参数说明：
16	 *   - T: 数据类型（float/int32_t）
17	 *   - BUFFER_MODE: 缓冲模式（0=单缓冲, 1=双缓冲）
18	 * 
19	 * 双缓冲模式（BUFFER_MODE=1）实现流水线并行：
20	 * - CopyIn: GM -> UB（输入数据搬运）
21	 * - Compute: UB 计算加法
22	 * - CopyOut: UB -> GM（输出数据搬运）
23	 */
24	#ifndef ADD_EXAMPLE_H
25	#define ADD_EXAMPLE_H
26	
27	#include "kernel_operator.h"
28	#include "kernel_tiling/kernel_tiling.h"
29	#include "add_example_tiling_data.h"
30	#include "add_example_tiling_key.h"
31	
32	namespace NsAddExample {
33	
34	using namespace AscendC;
35	
36	template <typename T, int BUFFER_MODE>
37	class AddExample {
38	    static constexpr int32_t BUFFER_NUM = BUFFER_MODE ? 2 : 1;
39	
40	public:
41	    __aicore__ inline AddExample(){};
42	
43	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, const AddExampleTilingData* tilingData);
44	    __aicore__ inline void Process();
45	
46	private:
47	    __aicore__ inline void CopyIn(int64_t progress, int64_t currentNum);
48	    __aicore__ inline void CopyOut(int64_t progress, int64_t currentNum);
49	    __aicore__ inline void Compute(int64_t currentNum);
50	
51	private:
52	    TPipe pipe;
53	    TQue<QuePosition::VECIN, 1> inputQueueX;
54	    TQue<QuePosition::VECIN, 1> inputQueueY;
55	    TQue<QuePosition::VECOUT, 1> outputQueueZ;
56	
57	    GlobalTensor<T> inputGMX;
58	    GlobalTensor<T> inputGMY;
59	    GlobalTensor<T> outputGMZ;
60	
61	    int64_t blockLength_ = 0;
62	    int64_t ubLength_ = 0;
63	};
64	
65	template <typename T, int BUFFER_MODE>
66	__aicore__ inline void AddExample<T, BUFFER_MODE>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, const AddExampleTilingData* tilingData)
67	{
68	    int64_t remainderLength = tilingData->totalNum - tilingData->blockFactor * AscendC::GetBlockIdx();
69	    blockLength_ = (remainderLength > tilingData->blockFactor) ? tilingData->blockFactor : remainderLength;
70	    ubLength_ = tilingData->ubFactor;
71	
72	    inputGMX.SetGlobalBuffer((__gm__ T*)x + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
73	    inputGMY.SetGlobalBuffer((__gm__ T*)y + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
74	    outputGMZ.SetGlobalBuffer((__gm__ T*)z + tilingData->blockFactor * AscendC::GetBlockIdx(), blockLength_);
75	
76	    pipe.InitBuffer(inputQueueX, BUFFER_NUM, ubLength_ * sizeof(T));
77	    pipe.InitBuffer(inputQueueY, BUFFER_NUM, ubLength_ * sizeof(T));
78	    pipe.InitBuffer(outputQueueZ, BUFFER_NUM, ubLength_ * sizeof(T));
79	}
80	
81	template <typename T, int BUFFER_MODE>
82	__aicore__ inline void AddExample<T, BUFFER_MODE>::CopyIn(int64_t progress, int64_t currentNum)
83	{
84	    AscendC::LocalTensor<T> xLocal = inputQueueX.template AllocTensor<T>();
85	    AscendC::LocalTensor<T> yLocal = inputQueueY.template AllocTensor<T>();
86	    AscendC::DataCopyExtParams copyParams;
87	    copyParams.blockCount = 1;
88	    copyParams.blockLen = currentNum * sizeof(T);
89	    copyParams.srcStride = 0;
90	    copyParams.dstStride = 0;
91	    copyParams.rsv = 0;
92	    AscendC::DataCopyPad(xLocal, inputGMX[progress * ubLength_], copyParams, {false, 0, 0, static_cast<T>(0)});
93	    AscendC::DataCopyPad(yLocal, inputGMY[progress * ubLength_], copyParams, {false, 0, 0, static_cast<T>(0)});
94	    inputQueueX.EnQue(xLocal);
95	    inputQueueY.EnQue(yLocal);
96	}
97	
98	template <typename T, int BUFFER_MODE>
99	__aicore__ inline void AddExample<T, BUFFER_MODE>::CopyOut(int64_t progress, int64_t currentNum)
100	{
101	    AscendC::LocalTensor<T> zLocal = outputQueueZ.template DeQue<T>();
102	    AscendC::DataCopyExtParams copyParams;
103	    copyParams.blockCount = 1;
104	    copyParams.blockLen = currentNum * sizeof(T);
105	    copyParams.srcStride = 0;
106	    copyParams.dstStride = 0;
107	    copyParams.rsv = 0;
108	    AscendC::DataCopyPad(outputGMZ[progress * ubLength_], zLocal, copyParams);
109	    outputQueueZ.FreeTensor(zLocal);
110	}
111	
112	template <typename T, int BUFFER_MODE>
113	__aicore__ inline void AddExample<T, BUFFER_MODE>::Compute(int64_t currentNum)
114	{
115	    AscendC::LocalTensor<T> xLocal = inputQueueX.template DeQue<T>();
116	    AscendC::LocalTensor<T> yLocal = inputQueueY.template DeQue<T>();
117	    AscendC::LocalTensor<T> zLocal = outputQueueZ.template AllocTensor<T>();
118	    AscendC::Add(zLocal, xLocal, yLocal, currentNum);
119	    outputQueueZ.template EnQue<T>(zLocal);
120	    inputQueueX.FreeTensor(xLocal);
121	    inputQueueY.FreeTensor(yLocal);
122	}
123	
124	template <typename T, int BUFFER_MODE>
125	__aicore__ inline void AddExample<T, BUFFER_MODE>::Process()
126	{
127	    int64_t loopCount = (blockLength_ + ubLength_ - 1) / ubLength_;
128	    for (int64_t i = 0; i < loopCount; i++) {
129	        int64_t currentNum = (i == (loopCount - 1)) ? (blockLength_ - ubLength_ * i) : ubLength_;
130	        CopyIn(i, currentNum);
131	        Compute(currentNum);
132	        CopyOut(i, currentNum);
133	    }
134	}
135	
136	} // namespace NsAddExample
137	#endif // ADD_EXAMPLE_H
138

