    add_kernel<half><<<1, nullptr, stream>>>(x, y, z, totalLength, blockLength, ubLength, alpha);
}

void launch_add_kernel_bfloat16(GM_ADDR x, GM_ADDR y, GM_ADDR z,
    int64_t totalLength, int64_t blockLength, int64_t ubLength, float alpha, void* stream) {
    add_kernel<bfloat16_t><<<1, nullptr, stream>>>(x, y, z, totalLength, blockLength, ubLength, alpha);
}

