{"content": "#include <ATen/Operators.h>
#include <torch/all.h>
#include <torch/library.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "torch_npu/csrc/framework/OpCommand.h"
#include "../op_kernel/add_launch.h"

namespace cann_bench {

// schema 注册 —— 与 proto.yaml schema 逐字一致
// schema: add(Tensor x, Tensor y, Scalar alpha=1.0) -> Tensor
TORCH_LIBRARY_FRAGMENT(cann_bench, m)
{
    m.def("add(Tensor x, Tensor y, Scalar alpha=1.0) -> Tensor");
}

// Meta 函数（输出 shape/dtype 推导）
torch::Tensor add_meta(const torch::Tensor &x, const torch::Tensor &y,
                       const c10::Scalar &alpha) {
    return torch::add(x, y, alpha);
}

TORCH_LIBRARY_IMPL(cann_bench, Meta, m)
{
    m.impl("add", add_meta);
}

// NPU 实现（调 kernel launch）
torch::Tensor add_npu(const torch::Tensor &x, const torch::Tensor &y,
                      const c10::Scalar &alpha) {
    const c10::OptionalDeviceGuard guard(x.device());

    // 处理广播：将输入 expand 到相同 shape
    torch::Tensor x_processed = x;
    torch::Tensor y_processed = y;
    if (x.sizes() != y.sizes()) {
        auto outputShape = torch::broadcast_shapes({x.sizes(), y.sizes()});
        x_processed = x.expand(outputShape);
        y_processed = y.expand(outputShape);
    }

    auto z = torch::empty_like(x_processed);
    auto stream = c10_npu::getCurrentNPUStream().stream(false);

    int64_t totalLength = x_processed.numel();
    int64_t blockSize = 2048;  // UB tile size
    int64_t blockLength = (totalLength + blockSize - 1) / blockSize;
    int64_t ubLength = blockSize;

    auto x_ptr = (GM_ADDR)x_processed.data_ptr();
    auto y_ptr = (GM_ADDR)y_processed.data_ptr();
    auto z_ptr = (GM_ADDR)z.data_ptr();

    float alphaVal = alpha.to<float>();

    auto acl_call = [=]() -> int {
        auto dtype = x_processed.scalar_type();
        if      (dtype == torch::kFloat32) {
            launch_add_kernel_float(x_ptr, y_ptr, z_ptr, totalLength, blockLength, ubLength, alphaVal, stream);
        } else if (dtype == torch::kFloat16) {
            launch_add_kernel_half(x_ptr, y_ptr, z_ptr, totalLength, blockLength, ubLength, alphaVal, stream);
        } else if (dtype == torch::kBFloat16) {
            launch_add_kernel_bfloat16(x_ptr, y_ptr, z_ptr, totalLength, blockLength, ubLength, alphaVal, stream);
        } else {
            return -1;
        }
        return 0;
    };

    at_npu::native::OpCommand::RunOpApi("Add", acl_call);
    return z;
}

TORCH_LIBRARY_IMPL(cann_bench, PrivateUse1, m)
{
    m.impl("add", add_npu);
}

} // namespace cann_bench
