11	/*!
12	 * \file add_kernel.cpp
13	 * \brief Add 算子 kernel 实现（arch22 架构，Ascend910B）
14	 *
15	 * 计算逻辑：output = x + alpha * y
16	 * 支持数据类型：float32, float16, bfloat16
17	 * 缓冲模式：双缓冲（BUFFER_MODE=1）实现流水线并行
18	 */
19	
20	#include "kernel_operator.h"
21	#include "kernel_tiling/kernel_tiling.h"
22	
23	using namespace AscendC;
24	
25	constexpr static int64_t PIPELINE_DEPTH = 2;
26	
27	template <typename T>
28	class KernelAdd {
29	public:
30	    __aicore__ inline KernelAdd() {}
31	
32	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
33	                                int64_t totalLength, int64_t blockLength,
34	                                int64_t ubLength, float alpha)
35	    {
36	        int64_t remainderLength = totalLength - blockLength * GetBlockIdx();
37	        if (remainderLength > blockLength) remainderLength = blockLength;
38	        if (remainderLength < 0) remainderLength = 0;
39	
40	        blockLength_ = remainderLength;
41	        ubLength_ = ubLength;
42	        alpha_ = alpha;
43	
44	        xGm_.SetGlobalBuffer((__gm__ T *)x + blockLength_ * GetBlockIdx(), blockLength_);
45	        yGm_.SetGlobalBuffer((__gm__ T *)y + blockLength_ * GetBlockIdx(), blockLength_);
46	        zGm_.SetGlobalBuffer((__gm__ T *)z + blockLength_ * GetBlockIdx(), blockLength_);
47	
48	        pipe_.InitBuffer(inQueueX_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
49	        pipe_.InitBuffer(inQueueY_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
50	        pipe_.InitBuffer(outQueueZ_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
51	    }
52	
53	    __aicore__ inline void Process()
54	    {
55	        int64_t loopCount = (blockLength_ + ubLength_ - 1) / ubLength_;
56	        for (int64_t i = 0; i < loopCount; ++i) {
57	            int64_t currentNum = (i == (loopCount - 1)) ? (blockLength_ - ubLength_ * i) : ubLength_;
58	            CopyIn(i, currentNum);
59	            Compute(currentNum);
60	            CopyOut(i, currentNum);
61	        }
62	    }
63	
64	private:
65	    __aicore__ inline void CopyIn(int64_t progress, int64_t currentNum)
66	    {
67	        LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
68	        LocalTensor<T> yLocal = inQueueY_.AllocTensor<T>();
69	
70	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(currentNum * sizeof(T)), 0, 0, 0};
71	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, static_cast<T>(0)};
72	
73	        DataCopyPad(xLocal, xGm_[progress * ubLength_], copyParams, padParams);
74	        DataCopyPad(yLocal, yGm_[progress * ubLength_], copyParams, padParams);
75	
76	        inQueueX_.EnQue(xLocal);
77	        inQueueY_.EnQue(yLocal);
78	    }
