28	torch::Tensor add_npu(const torch::Tensor &x, const torch::Tensor &y,
29	                      const c10::Scalar &alpha) {
30	    const c10::OptionalDeviceGuard guard(x.device());
31	
32	    // 处理广播：将输入 expand 到相同 shape
33	    torch::Tensor x_processed = x;
34	    torch::Tensor y_processed = y;
35	    if (x.sizes() != y.sizes()) {
36	        auto outputShape = torch::broadcast_shapes({x.sizes(), y.sizes()});
37	        x_processed = x.expand(outputShape);
38	        y_processed = y.expand(outputShape);
39	    }
40	
41	    auto dtype = x_processed.scalar_type();
42	    int64_t totalLength = x_processed.numel();
43	    int64_t blockSize = 2048;
44	    int64_t blockLength = (totalLength + blockSize - 1) / blockSize;
45	    int64_t ubLength = blockSize;
46	
47	    auto x_ptr = (GM_ADDR)x_processed.data_ptr();
48	    auto y_ptr = (GM_ADDR)y_processed.data_ptr();
49	    auto z = torch::empty_like(x_processed);
50	    auto z_ptr = (GM_ADDR)z.data_ptr();
51	
52	    float alphaVal = alpha.to<float>();
53	    auto stream = c10_npu::getCurrentNPUStream().stream(false);
54	
55	    auto acl_call = [=]() -> int {
56	        if      (dtype == torch::kFloat32) {
57	            launch_add_kernel_float(x_ptr, y_ptr, z_ptr, totalLength, blockLength, ubLength, alphaVal, stream);
58	        } else if (dtype == torch::kFloat16) {
59	            launch_add_kernel_half(x_ptr, y_ptr, z_ptr, totalLength, blockLength, ubLength, alphaVal, stream);
60	        } else if (dtype == torch::kBFloat16) {
61	            // bfloat16 在 arch22 不支持 Muls，转换为 fp32 计算后再转回
62	            auto x_fp32 = x_processed.to(torch::kFloat32);
63	            auto y_fp32 = y_processed.to(torch::kFloat32);
64	            auto z_fp32 = torch::empty_like(x_fp32);
65	            int64_t bf_totalLength = x_fp32.numel();
66	            launch_add_kernel_float(
67	                (GM_ADDR)x_fp32.data_ptr(), (GM_ADDR)y_fp32.data_ptr(),
68	                (GM_ADDR)z_fp32.data_ptr(), bf_totalLength, blockLength, ubLength,
69	                alphaVal, stream);
70	            z = z_fp32.to(torch::kBFloat16);
71	        } else {
72	            return -1;
73	        }
74	        return 0;
75	    };
76	
77	    at_npu::native::OpCommand::RunOpApi("Add", acl_call);
78	    return z;
79	}
