        std::vector<int64_t> outputShape(maxLen, 1);
        for (int64_t i = 0; i < xLen; ++i) {
            outputShape[maxLen - xLen + i] = std::max(outputShape[maxLen - xLen + i], xSizes[i]);
        }
        for (int64_t i = 0; i < yLen; ++i) {
            outputShape[maxLen - yLen + i] = std::max(outputShape[maxLen - yLen + i], ySizes[i]);
        }
