#include <torch_npu/csrc/framework/OpCommand.h>

using namespace at;

#define DEVICE c10::DeviceType::PrivateUse1

// Helper: check if two floats are close
bool close(float a, float b, float rtol=1e-3, float atol=1e-3) {
    return std::abs(a - b) <= atol + rtol * std::abs(b);
}

// Helper: convert torch tensor to float vector
std::vector<float> tensor_to_vec(const Tensor &t) {
    auto cpu = t.cpu();
    if (cpu.scalar_type() == ScalarType::Float) {
        auto acc = cpu.accessor<float, 1>();
        return {acc.data(), acc.data() + cpu.numel()};
    } else if (cpu.scalar_type() == ScalarType::Half) {
        auto acc = cpu.accessor<at::Half, 1>();
        std::vector<float> result(cpu.numel());
        for (int64_t i = 0; i < cpu.numel(); ++i) result[i] = (float)acc[i];
        return result;
    }
    return {};
}

// Helper: compare two float vectors
bool vectors_close(const std::vector<float> &a, const std::vector<float> &b,
                   float rtol=1e-3, float atol=1e-3) {
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i) {
        if (!close(a[i], b[i], rtol, atol)) return false;
    }
    return true;
}

struct TestCase {
    std::vector<int64_t> shape;
    std::string dtype_str;
    float alpha;
};

int main(int argc, char *argv[]) {
    int pass_count = 0;
    int fail_count = 0;

    // Test cases
    std::vector<TestCase> cases = {
        // float32 cases
        {{{3, 4, 5}, "float32", 1.0f},
        {{{2, 3, 4}, "float32", 0.5f},
        {{{4, 5, 6}, "float32", 2.0f},
        {{{}, "float32", 1.5f},  // scalar
        {{{10}, "float32", 0.1f},
        // float16 cases
        {{{3, 4, 5}, "float16", 1.0f},
        {{{2, 3, 4}, "float16", 0.5f},
        {{{4, 5, 6}, "float16", 2.0f},
        {{{}, "float16", 1.5f},  // scalar
        {{{10}, "float16", 0.1f},
    };

    for (const auto &tc : cases) {
        try {
            // Create tensors on NPU
            ScalarType dtype = (tc.dtype_str == "float32") ? ScalarType::Float : ScalarType::Half;
            Tensor x = at::randn(tc.shape, dtype).to(DEVICE);
            Tensor y = at::randn(tc.shape, dtype).to(DEVICE);
            float alpha = tc.alpha;

            // Golden output on CPU
            Tensor golden_cpu = at::add(x.cpu(), y.cpu(), alpha);

            // AscendC kernel output
            int64_t totalLength = x.numel();
            int64_t blockSize = 2048;
            int64_t blockLength = (totalLength + blockSize - 1) / blockSize;
            int64_t ubLength = blockSize;

            auto stream = c10_npu::getCurrentNPUStream().stream(false);

            Tensor z;
            if (dtype == ScalarType::Float) {
                z = at::empty_like(x);
                launch_add_kernel_float(
                    x.data_ptr(), y.data_ptr(), z.data_ptr(),
                    totalLength, blockLength, ubLength, alpha, stream);
            } else {
                z = at::empty_like(x);
                launch_add_kernel_half(
                    x.data_ptr(), y.data_ptr(), z.data_ptr(),
                    totalLength, blockLength, ubLength, alpha, stream);
            }

            // Compare
            auto z_cpu = z.cpu();
            auto diff = (z_cpu - golden_cpu).abs();
            float maxDiff = diff.max().item<float>();
            float maxRelDiff = (diff / (golden_cpu.abs() + 1e-8)).max().item<float>();

            bool pass = (maxDiff < 1e-3 + 1e-3 * golden_cpu.abs().max().item<float>());
            if (pass) {
                pass_count++;
                std::cout << "PASS | dtype=" << tc.dtype_str
                          << " shape=" << tc.shape
                          << " alpha=" << alpha
                          << " max_diff=" << maxDiff << std::endl;
            } else {
                fail_count++;
                std::cout << "FAIL | dtype=" << tc.dtype_str
                          << " shape=" << tc.shape
                          << " alpha=" << alpha
                          << " max_diff=" << maxDiff
                          << " max_rel_diff=" << maxRelDiff << std::endl;
            }
        } catch (const std::exception &e) {
            fail_count++;
            std::cout << "ERROR | dtype=" << tc.dtype_str
                      << " shape=" << tc.shape
                      << " alpha=" << alpha
                      << " exception=" << e.what() << std::endl;
        }
    }

    std::cout << "\n=== Results ===" << std::endl;
    std::cout << "Total: " << cases.size()
              << " | Pass: " << pass_count
              << " | Fail: " << fail_count << std::endl;

    return (fail_count == 0) ? 0 : 1;
}
