```cpp
#ifndef ADD_H
#define ADD_H

#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "add_tiling_data.h"

namespace NsAdd {

using namespace AscendC;

template <typename T, int BUFFER_MODE>
class Add {
    static constexpr int32_t BUFFER_NUM = BUFFER_MODE ? 2 : 1;

public:
    __aicore__ inline Add() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                const AddTilingData *tilingData)
    {
        int64_t remainderLength = tilingData->totalNum - tilingData->blockFactor * GetBlockIdx();
        if (remainderLength > tilingData->blockFactor) remainderLength = tilingData->blockFactor;
        if (remainderLength < 0) remainderLength = 0;
        blockLength_ = remainderLength;
        ubLength_ = tilingData->ubFactor;
        alpha_ = tilingData->alpha;

        xGm_.SetGlobalBuffer((__gm__ T *)x + tilingData->blockFactor * GetBlockIdx(), blockLength_);
        yGm_.SetGlobalBuffer((__gm__ T *)y + tilingData->blockFactor * GetBlockIdx(), blockLength_);
        zGm_.SetGlobalBuffer((__gm__ T *)z + tilingData->blockFactor * GetBlockIdx(), blockLength_);

        pipe_.InitBuffer(inQueueX_, BUFFER_NUM, ubLength_ * sizeof(T));
        pipe_.InitBuffer(inQueueY_, BUFFER_NUM, ubLength_ * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, BUFFER_NUM, ubLength_ * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t loopCount = (blockLength_ + ubLength_ - 1) / ubLength_;
        for (int64_t i = 0; i < loopCount; ++i) {
            int64_t currentNum = (i == (loopCount - 1)) ? (blockLength_ - ubLength_ * i) : ubLength_;
            CopyIn(i, currentNum);
            Compute(currentNum);
            CopyOut(i, currentNum);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t currentNum)
    {
        LocalTensor<T> xLocal = inQueueX_.AllocTensor<T>();
        LocalTensor<T> yLocal = inQueueY_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(currentNum * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, static_cast<T>(0)};
        DataCopyPad(xLocal, xGm_[progress * ubLength_], copyParams, padParams);
        DataCopyPad(yLocal, yGm_[progress * ubLength_], copyParams, padParams);
        inQueueX_.EnQue(xLocal);
        inQueueY_.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t currentNum)
    {
        LocalTensor<T> xLocal = inQueueX_.DeQue<T>();
        LocalTensor<T> yLocal = inQueueY_.DeQue<T>();
        LocalTensor<T> zLocal = outQueueZ_.AllocTensor<T>();
        T alphaVal = static_cast<T>(alpha_);
        AscendC::Muls(zLocal, yLocal, alphaVal, static_cast<int32_t>(currentNum));
        AscendC::Add(zLocal, xLocal, zLocal, static_cast<int32_t>(currentNum));
        outQueueZ_.EnQue(zLocal);
        inQueueX_.FreeTensor(xLocal);
        inQueueY_.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t currentNum)
    {
        LocalTensor<T> zLocal = outQueueZ_.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(currentNum * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(zGm_[progress * ubLength_], zLocal, copyParams);
        outQueueZ_.FreeTensor(zLocal);
    }

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> xGm_, yGm_, zGm_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ_;
    int64_t blockLength_ = 0, ubLength_ = 0;
    float alpha_ = 1.0f;
};

} // namespace NsAdd
#endif // ADD_H
