48	// 获取平台信息如ubSize, coreNum
49	static ge::graphStatus GetPlatformInfo(gert::TilingContext* context, uint64_t* ubSize, int64_t* coreNum)
50	{
51	    // 获取ubsize coreNum
52	    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
53	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
54	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
55	    *coreNum = ascendcPlatform.GetCoreNumAiv();
56	    OP_CHECK_IF(*coreNum == 0, OP_LOGE(context, "coreNum is 0"), return ge::GRAPH_FAILED);
57	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, *ubSize);
58	    OP_CHECK_IF(*ubSize == 0, OP_LOGE(context, "ubSize is 0"), return ge::GRAPH_FAILED);
59	    return ge::GRAPH_SUCCESS;
60	}
61	
62	// 获取属性，shape信息
63	static ge::graphStatus GetShapeAttrsInfo(gert::TilingContext* context, int64_t* totalIdx, ge::DataType* dataType)
64	{
65	    // 获取输入shape信息
66	    auto inputX = context->GetInputShape(0);
67	    OP_CHECK_NULL_WITH_CONTEXT(context, inputX);
68	    // 如果输入shape 是标量 转换为{1}，否则保持原 shape 不变
69	    auto inputShapeX = EnsureNotScalar(inputX->GetStorageShape());
70	    auto inputY = context->GetInputShape(1);
71	    OP_CHECK_NULL_WITH_CONTEXT(context, inputY);
72	    auto inputShapeY = EnsureNotScalar(inputY->GetStorageShape());
73	    auto outZ = context->GetOutputShape(0);
74	    OP_CHECK_NULL_WITH_CONTEXT(context, outZ);
75	    auto outShapeZ = EnsureNotScalar(outZ->GetStorageShape());
76	
77	    // shape校验：确保输入和输出shape一致
78	    OP_CHECK_IF(
79	        inputShapeX.GetShapeSize() != inputShapeY.GetShapeSize() ||
80	            inputShapeX.GetShapeSize() != outShapeZ.GetShapeSize(),
81	        OP_LOGE(
82	            context, "AddExample: input and output shape size mismatch: x=%ld, y=%ld, z=%ld",
83	            inputShapeX.GetShapeSize(), inputShapeY.GetShapeSize(), outShapeZ.GetShapeSize()),
84	        return ge::GRAPH_FAILED);
85	
86	    // 获取shape dim值
87	    *totalIdx = inputShapeX.GetShapeSize();
88	    // dtype校验
89	    const std::set<ge::DataType> supportedDtype = {ge::DT_FLOAT, ge::DT_INT32};
90	    auto inputDesc = context->GetInputDesc(0);
91	    OP_CHECK_NULL_WITH_CONTEXT(context, inputDesc);
92	    *dataType = inputDesc->GetDataType();
93	    OP_CHECK_IF(supportedDtype.count(*dataType) == 0, OP_LOGE(context, "invalid dtype"), return ge::GRAPH_FAILED);
94	    return ge::GRAPH_SUCCESS;
95	}
