97	// 即使 workspace 大小为 0，也必须调用 GetWorkspaceSizes 声明 workspace slot，否则运行时不会为 kernel 分配 workspace 指针
98	static ge::graphStatus GetWorkspaceSize(gert::TilingContext* context)
99	{
100	    size_t* currentWorkspace = context->GetWorkspaceSizes(WORKSPACE_NUM);
101	    OP_CHECK_NULL_WITH_CONTEXT(context, currentWorkspace);
102	    currentWorkspace[0] = WS_SYS_SIZE;
103	    return ge::GRAPH_SUCCESS;
104	}
