106	// tiling 分发入口
107	static ge::graphStatus AddExampleTilingFunc(gert::TilingContext* context)
108	{
109	    // 1、获取平台运行信息
110	    uint64_t ubSize;
111	    int64_t coreNum;
112	    OP_CHECK_IF(
113	        GetPlatformInfo(context, &ubSize, &coreNum) != ge::GRAPH_SUCCESS, OP_LOGE(context, "GetPlatformInfo error"),
114	        return ge::GRAPH_FAILED);
115	    // 2、获取shape、属性信息
116	    int64_t totalIdx;
117	    ge::DataType dataType;
118	    OP_CHECK_IF(
119	        GetShapeAttrsInfo(context, &totalIdx, &dataType) != ge::GRAPH_SUCCESS,
120	        OP_LOGE(context, "GetShapeAttrsInfo error"), return ge::GRAPH_FAILED);
121	    // 3、获取WorkspaceSize信息
122	    OP_CHECK_IF(
123	        GetWorkspaceSize(context) != ge::GRAPH_SUCCESS, OP_LOGE(context, "GetWorkspaceSize error"),
124	        return ge::GRAPH_FAILED);
125	
126	    // 4、设置tiling信息, TilingData空间由kernel侧的REGISTER_TILING_DEFAULT决定
127	    AddExampleTilingData* tiling = context->GetTilingData<AddExampleTilingData>();
128	    OP_CHECK_NULL_WITH_CONTEXT(context, tiling);
129	    OP_CHECK_IF(
130	        memset_s(tiling, sizeof(AddExampleTilingData), 0, sizeof(AddExampleTilingData)) != EOK,
131	        OP_LOGE(context, "set tiling data error"), return ge::GRAPH_FAILED);
132	    
133	    // 空Tensor 检查，避免后续除零风险
134	    if (totalIdx == 0) {
135	        context->SetBlockDim(1);
136	        ASCENDC_TPL_SEL_PARAM(context, static_cast<uint32_t>(dataType), 0);
137	        return ge::GRAPH_SUCCESS;
138	    }
139	
140	    // 多核切分：将总元素按核数均分，按 DMA 最小粒度 (32B) 对齐
141	    // blockFactor 必须按 blockAlign 向上对齐，否则相邻核 CopyOut 写 GM 时
142	    // DMA 实际写入范围会超过 blockLen，覆盖相邻核的数据
143	    int64_t ubBlockSize = Ops::Base::GetUbBlockSize(context);
144	    tiling->totalNum = totalIdx;
145	    tiling->blockFactor = CeilAlign(CeilDiv(totalIdx, coreNum), ubBlockSize);
146	    int64_t usedCoreNum = Ops::Base::CeilDiv(totalIdx, tiling->blockFactor);
147	
148	    // UB 切分：按可用 UB 大小和 tensor 数量均分
149	    // 双缓冲时 UB tensor 数量：2输入×2(双缓冲) + 1输出×2(双缓冲) = 6
150	    // 单缓冲时 UB tensor 数量：2输入×1 + 1输出×1 = 3
151	    // 公式：(UB总大小 / 类型大小) / tensor数量，然后按 UB 块大小对齐
152	    uint64_t useDoubleBuffer = (totalIdx > MIN_SPLIT_THRESHOLD) ? 1 : 0;
153	    int64_t bufferNum = useDoubleBuffer ? DOUBLE_BUF_TENSOR_COUNT : SINGLE_BUF_TENSOR_COUNT;
154	    tiling->ubFactor = Ops::Base::FloorAlign(Ops::Base::FloorDiv((static_cast<int64_t>(ubSize) / TYPE_SIZE), bufferNum), ubBlockSize);
155	
156	    context->SetBlockDim(usedCoreNum);
157	
158	    // 5、设置 TilingKey
159	    // 参数顺序与add_example_tiling_key.h中 ASCENDC_TPL_ARGS_DECL 定义一致
160	    // 参数会映射到add_example_arch22.cpp中kernel 入口模板参数：add_example<D_T_X, BUFFER_MODE>
161	    uint32_t dTypeX = static_cast<uint32_t>(dataType);
162	    ASCENDC_TPL_SEL_PARAM(context, dTypeX, useDoubleBuffer);
163	    return ge::GRAPH_SUCCESS;
164	}
