using namespace AscendC;

constexpr static int64_t PIPELINE_DEPTH = 2;

template <typename T>
class KernelAdd {
public:
    __aicore__ inline KernelAdd() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                int64_t totalLength, int64_t blockLength,
                                int64_t ubLength, float alpha)
    {
        int64_t remainderLength = totalLength - blockLength * GetBlockIdx();
        if (remainderLength > blockLength) remainderLength = blockLength;
        if (remainderLength < 0) remainderLength = 0;
        blockLength_ = remainderLength;
        ubLength_ = ubLength;
        alpha_ = alpha;

        xGm_.SetGlobalBuffer((__gm__ T *)x + blockLength_ * GetBlockIdx(), blockLength_);
        yGm_.SetGlobalBuffer((__gm__ T *)y + blockLength_ * GetBlockIdx(), blockLength_);
        zGm_.SetGlobalBuffer((__gm__ T *)z + blockLength_ * GetBlockIdx(), blockLength_);

        pipe_.InitBuffer(inQueueX_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
        pipe_.InitBuffer(inQueueY_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
        pipe_.InitBuffer(outQueueZ_, PIPELINE_DEPTH, ubLength_ * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t loopCount = (blockLength_ + ubLength_ - 1) / ubLength_;
        for (int64_t i = 0; i < loopCount; ++i) {
            int64_t currentNum = (i == (loopCount - 1)) ? (blockLength_ - ubLength_ * i) : ubLength_;
            CopyIn(i, currentNum);
            Compute(currentNum);
            CopyOut(i, currentNum);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t currentNum)
    {
        LocalTensor<T> xLocal = inQueueX_.template AllocTensor<T>();
        LocalTensor<T> yLocal = inQueueY_.template AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(currentNum * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, static_cast<T>(0)};
        DataCopyPad(xLocal, xGm_[progress * ubLength_], copyParams, padParams);
        DataCopyPad(yLocal, yGm_[progress * ubLength_], copyParams, padParams);
        inQueueX_.EnQue(xLocal);
        inQueueY_.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t currentNum)
    {
        LocalTensor<T> xLocal = inQueueX_.template DeQue<T>();
        LocalTensor<T> yLocal = inQueueY_.template DeQue<T>();
        LocalTensor<T> zLocal = outQueueZ_.template AllocTensor<T>();
        T alphaVal = static_cast<T>(alpha_);
        AscendC::Muls(zLocal, yLocal, alphaVal, static_cast<int32_t>(currentNum));
        AscendC::Add(zLocal, xLocal, zLocal, static_cast<int32_t>(currentNum));
        outQueueZ_.EnQue(zLocal);
        inQueueX_.FreeTensor(xLocal);
        inQueueY_.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t currentNum)
    {
        LocalTensor<T> zLocal = outQueueZ_.template DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(currentNum * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(zGm_[progress * ubLength_], zLocal, copyParams);
        outQueueZ_.FreeTensor(zLocal);
    }

    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> xGm_, yGm_, zGm_;
    AscendC::TQue<AscendC::TPosition::VECIN, PIPELINE_DEPTH> inQueueX_;
    AscendC::TQue<AscendC::TPosition::VECIN, PIPELINE_DEPTH> inQueueY_;
    AscendC::TQue<AscendC::TPosition::VECOUT, PIPELINE_DEPTH> outQueueZ_;
    int64_t blockLength_ = 0, ubLength_ = 0;
    float alpha_ = 1.0f;
};

template <typename T>
__global__ __aicore__ void add_kernel(GM_ADDR x, GM_ADDR y, GM_ADDR z,
    int64_t totalLength, int64_t blockLength, int64_t ubLength, float alpha)
{
    KernelAdd<T> op;
    op.Init(x, y, z, totalLength, blockLength, ubLength, alpha);
    op.Process();
}

